class Solution {
public:
    int numberOfWays(int n) {
        long long MOD = 1e9 + 7;
        vector<long long> dp(n + 1, 0);
        dp[0] = 1;
        for (int c : {1, 2, 6}) {
            for (int j = c; j <= n; ++j) {
                dp[j] = (dp[j] + dp[j - c]) % MOD;
            }
        }
        long long ans = dp[n];
        if (n >= 4) ans = (ans + dp[n - 4]) % MOD;
        if (n >= 8) ans = (ans + dp[n - 8]) % MOD;
        return ans;
    }
};

class Solution {
    public int numberOfWays(int n) {
        long MOD = 1_000_000_007L;
        long[] dp = new long[n + 1];
        dp[0] = 1;
        int[] coins = {1, 2, 6};
        for (int c : coins) {
            for (int j = c; j <= n; ++j) {
                dp[j] = (dp[j] + dp[j - c]) % MOD;
            }
        }
        long ans = dp[n];
        if (n >= 4) ans = (ans + dp[n - 4]) % MOD;
        if (n >= 8) ans = (ans + dp[n - 8]) % MOD;
        return (int) ans;
    }
}

